import Foundation
import XCTest
@testable import KaitoKit

/// Generated by the RAR executable only; no third-party implementation sources.
final class RARIOTests: XCTestCase {
    private static let fixtures: Result<URL, Error> = Result { try makeFixtures() }
    private static func modes(_ version: Int) -> [String] {
        ["stored", "compressed", "solid", "encrypted", "encrypted-compressed", "headers"]
            + (version == 5 ? ["hashed", "encrypted-no-check"] : [])
    }
    private var baseline: Bool { ProcessInfo.processInfo.environment["RAR_IO_BASELINE"] == "1" }

    private static func makeFixtures() throws -> URL {
        let executable = ProcessInfo.processInfo.environment["KAITOKIT_RAR4_EXECUTABLE"]
            ?? "/Users/nagash/.local/opt/rar-6.24/rar"
        try ExternalTool.requireExecutable(executable, requireVariable: nil,
                                          reason: "RAR 6.x is needed to generate -ma4 IO fixtures")
        let directory = try ProcessInfo.processInfo.environment["RAR_IO_FIXTURES"].map {
            URL(fileURLWithPath: $0, isDirectory: true)
        } ?? ZipTestSupport.temporaryDirectory(label: "rar-io")
        if FileManager.default.fileExists(atPath: directory.appendingPathComponent("ready-v3").path) {
            return directory
        }
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        let input = directory.appendingPathComponent("input", isDirectory: true)
        try FileManager.default.createDirectory(at: input, withIntermediateDirectories: true)
        for size in [96, 192] {
            let folder = input.appendingPathComponent("small-\(size)", isDirectory: true)
            try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
            for index in 0..<64 {
                let bytes = RAR5TestSupport.deterministicPayload(count: size << 10, seed: UInt64(index + size))
                try bytes.write(to: folder.appendingPathComponent(String(format: "%03d.bin", index)))
            }
            for solid in [false, true] {
                _ = try ZipTestSupport.checkedRun(executable, arguments: [
                    "a", "-ma4", "-idq", "-m3", solid ? "-s" : "-s-", "-ep1",
                    directory.appendingPathComponent("headers-\(size)-\(solid).rar").path,
                    "small-\(size)/*",
                ], currentDirectory: input)
            }
        }
        let payload = RAR5TestSupport.deterministicPayload(count: (2 << 20) + 137, seed: 0x524152494f)
        try payload.write(to: input.appendingPathComponent("split.bin"))
        try payload.prefix(65536).write(to: input.appendingPathComponent("tail.bin"))
        for version in [4, 5] {
            for mode in Self.modes(version) {
                let output = directory.appendingPathComponent("v\(version)-\(mode)", isDirectory: true)
                if FileManager.default.fileExists(atPath: output.path) {
                    try FileManager.default.removeItem(at: output)
                }
                try FileManager.default.createDirectory(at: output, withIntermediateDirectories: true)
                var arguments = ["a", "-ma\(version)", "-idq", mode == "solid" ? "-s" : "-s-", "-v256k",
                                 ["compressed", "solid", "encrypted-compressed", "hashed", "encrypted-no-check"].contains(mode) ? "-m3" : "-m0"]
                if mode.hasPrefix("encrypted") { arguments.append("-psecret") }
                if mode == "headers" { arguments.append("-hpsecret") }
                if mode == "hashed" || mode == "encrypted-no-check" { arguments.append("-htb") }
                arguments += [output.appendingPathComponent("chain.rar").path, "split.bin"]
                if mode == "solid" { arguments.append("tail.bin") }
                _ = try ZipTestSupport.checkedRun(executable, arguments: arguments, currentDirectory: input)
                if mode == "encrypted-no-check" {
                    for volume in try FileManager.default.contentsOfDirectory(at: output, includingPropertiesForKeys: nil) {
                        var bytes = [UInt8](try Data(contentsOf: volume))
                        for layout in try volumeLayouts(in: bytes).reversed() {
                            guard bytes[layout.body.lowerBound] == 2 else { continue }
                            try RAR5TestSupport.removeFileEncryptionCheck(&bytes, layout: layout)
                        }
                        try Data(bytes).write(to: volume)
                    }
                }
            }
        }
        try Data().write(to: directory.appendingPathComponent("ready-v3"))
        return directory
    }

    private static func volumeLayouts(in bytes: [UInt8]) throws -> [RAR5TestSupport.BlockLayout] {
        // RAR 6.x pads non-final volumes after ENDARC. The existing mutation
        // helper expects an archive ending exactly at the last block.
        var offset = RAR5Reader.signature.count
        while offset + 4 < bytes.count {
            var cursor = RAR5ByteCursor(Array(bytes[(offset + 4)...]))
            let size = Int(try cursor.readVInt())
            let bodyStart = offset + 4 + cursor.offset
            let type = try cursor.readVInt()
            let flags = try cursor.readVInt()
            if flags & 1 != 0 { _ = try cursor.readVInt() }
            let dataSize = flags & 2 != 0 ? Int(try cursor.readVInt()) : 0
            let end = bodyStart + size + dataSize
            guard end <= bytes.count else { throw KaitoError.truncated }
            if type == 5 { return try RAR5TestSupport.blockLayouts(in: Array(bytes.prefix(end))) }
            offset = end
        }
        throw KaitoError.truncated
    }

    func testGeneratedRAR4HeaderReadCountsAndBytes() throws {
        let directory = try Self.fixtures.get()
        for size in [96, 192] {
            for solid in [false, true] {
                let bytes = try Data(contentsOf: directory.appendingPathComponent("headers-\(size)-\(solid).rar"))
                var expected: [ArchiveEntry]?
                var counts: [Int] = []
                for latency in [InputLatency.low, .high, .automatic] {
                    let source = CallCountingByteSource(DataByteSource(bytes), reportsNonLocalVolume: true)
                    var options = ReaderOptions(decodeThreads: 1)
                    options.inputLatency = latency
                    let reader = try RAR4Reader(source: source, options: options)
                    XCTAssertEqual(reader.entries.count, 64)
                    if let expected { XCTAssertEqual(reader.entries, expected) }
                    expected = reader.entries
                    counts.append(source.readCount)
                    print("RAR-IO headers size=\(size) solid=\(solid) latency=\(latency) reads=\(source.readCount) bytes=\(source.readBytes)")
                    // Listing counts above exclude extraction; compare every byte to generator input.
                    for entry in reader.entries {
                        let expected = try Data(contentsOf: directory.appendingPathComponent("input/small-\(size)/\(entry.name)"))
                        XCTAssertEqual(try reader.stream(for: entry, limits: options.limits).readAll(), expected)
                    }
                }
                if !baseline { XCTAssertLessThan(counts[1], counts[0] / 2) }
                XCTAssertEqual(counts[1], counts[2])
            }
        }
    }

    func testGeneratedSplitSourceBytesAndIdentity() throws {
        let directory = try Self.fixtures.get()
        let expected = try Data(contentsOf: directory.appendingPathComponent("input/split.bin"))
        for version in [4, 5] {
            for mode in Self.modes(version) {
                let folder = directory.appendingPathComponent("v\(version)-\(mode)")
                let first = try firstVolume(in: folder)
                for memoryLimit: UInt64 in [0, 4 << 20] {
                    let counter = RARIOFileCounter()
                    try FileByteSource.$testingDidRead.withValue({ source, _, count in counter.observe(source, count) }) {
                        var options = ReaderOptions(password: "secret", decodeThreads: 1)
                        options.limits.inMemorySingleFileLimit = memoryLimit
                        options.limits.stagingFreeSpaceReserve = 0
                        let reader = try ArchiveReader.open(url: first, options: options)
                        let entry = try XCTUnwrap(reader.entries.first)
                        counter.beginExtraction()
                        XCTAssertEqual(try reader.read(entry), expected)
                        let measured = counter.bytes
                        print("RAR-IO split version=\(version) mode=\(mode) memoryLimit=\(memoryLimit) reads=\(counter.reads) bytes=\(measured) packed=\(entry.compressedSize ?? 0)")
                        if !baseline {
                            // Original volumes, excluding listing/header guards and local staging IO.
                            XCTAssertLessThanOrEqual(measured, Int(entry.compressedSize ?? 0) + 4096)
                        }
                        XCTAssertEqual(try reader.reopen().read(entry), expected)
                    }
                }
            }
        }
    }

    func testHEADListingExtractionAndErrorEquivalence() throws {
        let directory = try Self.fixtures.get()
        var records: [String: String] = [:]
        for version in [4, 5] {
            for mode in Self.modes(version) {
                let original = directory.appendingPathComponent("v\(version)-\(mode)")
                for variant in ["valid", "corrupt-header", "truncated-header", "corrupt-data", "corrupt-last-data", "missing-volume"] {
                    let scratch = try ZipTestSupport.temporaryDirectory(label: "rar-io-errors")
                    defer { try? FileManager.default.removeItem(at: scratch) }
                    let volumes = try volumeURLs(in: original)
                    for volume in volumes {
                        try FileManager.default.copyItem(at: volume, to: scratch.appendingPathComponent(volume.lastPathComponent))
                    }
                    let first = scratch.appendingPathComponent(volumes[0].lastPathComponent)
                    if variant == "missing-volume" {
                        try FileManager.default.removeItem(at: scratch.appendingPathComponent(volumes[1].lastPathComponent))
                    } else if variant != "valid" {
                        let target = variant == "corrupt-last-data"
                            ? scratch.appendingPathComponent(volumes.last!.lastPathComponent) : first
                        var data = try Data(contentsOf: target)
                        switch variant {
                        case "corrupt-header": data[version == 4 ? 9 : 14] ^= 0x80
                        case "truncated-header": data = Data(data.prefix(version == 4 ? 24 : 16))
                        case "corrupt-data", "corrupt-last-data": data[data.count / 2] ^= 0x80
                        default: break
                        }
                        try data.write(to: target)
                    }
                    for password in ["secret", "wrong", "<none>"] {
                        for high in [false, true] {
                            for recovery in [false, true] {
                                let key = "v\(version)/\(mode)/\(variant)/\(password)/\(high)/\(recovery)"
                                var options = ReaderOptions(password: password == "<none>" ? nil : password,
                                                            recoverDamagedArchives: recovery, decodeThreads: 1)
                                options.inputLatency = high ? .high : .low
                                for staging in ["memory", "disk", "unavailable"] {
                                    var selected = options
                                    if staging != "memory" { selected.limits.inMemorySingleFileLimit = 0 }
                                    records[key + "/" + staging] = staging == "unavailable"
                                        ? SingleFileMaterializer.$availableTemporarySpace.withValue({ 0 }) {
                                            outcome(first, options: selected)
                                        } : outcome(first, options: selected)
                                }
                            }
                        }
                    }
                }
            }
        }
        // RAR4 moderate-spacing windows also exercise malformed later headers and
        // physical truncation after the first window, compared directly with HEAD.
        for size in [96, 192] {
            for solid in [false, true] {
                let original = directory.appendingPathComponent("headers-\(size)-\(solid).rar")
                let bytes = try Data(contentsOf: original)
                let secondHeader = 20 + Int(LittleEndian.uint16([UInt8](bytes), at: 25))
                    + Int(LittleEndian.uint32([UInt8](bytes), at: 27))
                for variant in ["valid", "corrupt-later-header", "truncated-later-header"] {
                    let scratch = try ZipTestSupport.temporaryDirectory(label: "rar-io-later-header")
                    defer { try? FileManager.default.removeItem(at: scratch) }
                    let target = scratch.appendingPathComponent("test.rar")
                    var data = bytes
                    if variant == "corrupt-later-header" { data[secondHeader + 2] ^= 0x80 }
                    if variant == "truncated-later-header" { data = Data(data.prefix(secondHeader + 5)) }
                    try data.write(to: target)
                    for high in [false, true] {
                        for recovery in [false, true] {
                            var options = ReaderOptions(recoverDamagedArchives: recovery, decodeThreads: 1)
                            options.inputLatency = high ? .high : .low
                            records["headers/\(size)/\(solid)/\(variant)/\(high)/\(recovery)"] = outcome(target, options: options)
                        }
                    }
                }
            }
        }
        let environment = ProcessInfo.processInfo.environment
        for (key, value) in records {
            var fields = key.split(separator: "/").map(String.init)
            fields[4] = "false"
            if fields[0] != "headers" { fields[6] = "memory" }
            XCTAssertEqual(value, records[fields.joined(separator: "/")], key)
        }
        if let path = environment["RAR_IO_RECORD"] {
            try JSONSerialization.data(withJSONObject: records, options: [.sortedKeys, .prettyPrinted])
                .write(to: URL(fileURLWithPath: path))
        }
        if let path = environment["RAR_IO_EXPECT"] {
            let expected = try JSONDecoder().decode([String: String].self, from: Data(contentsOf: URL(fileURLWithPath: path)))
            XCTAssertEqual(Set(records.keys), Set(expected.keys))
            for (key, value) in records { XCTAssertEqual(value, expected[key], key) }
        }
        print("RAR-IO equivalence cases=\(records.count)")
    }

    private func outcome(_ url: URL, options: ReaderOptions) -> String {
        var stage = "open"
        var result = ""
        do {
            let reader = try ArchiveReader.open(url: url, options: options)
            // Reflect the complete public listing, including all format-specific values, deterministically.
            for entry in reader.entries {
                result += "\(entry.index):\(entry.name):\(entry.rawName.bytes):\(String(describing: entry.rawName.declaredEncoding)):\(entry.rawName.isDirectoryHint):\(entry.pathComponents):\(entry.kind):\(String(describing: entry.uncompressedSize)):\(String(describing: entry.compressedSize)):\(String(describing: entry.modificationDate)):\(String(describing: entry.posixPermissions)):\(entry.isEncrypted):\(entry.isIncomplete):\(entry.solidGroup):\(String(describing: entry.crc32)):\(entry.methodDescription):\(entry.formatSpecific.sorted { $0.key < $1.key })\n"
            }
            for entry in reader.entries {
                stage = "stream"
                let stream = try reader.stream(entry)
                stage = "read"
                var output = Data()
                var buffer = [UInt8](repeating: 0, count: 32 << 10)
                do {
                    while true {
                        let count = try buffer.withUnsafeMutableBytes { try stream.read(into: $0) }
                        if count == 0 { break }
                        output.append(contentsOf: buffer[..<count])
                    }
                } catch {
                    result += "emitted=\(output.count):\(output.sha256Hex)\n"
                    throw error
                }
                result += "output=\(output.count):\(output.sha256Hex)\n"
            }
            return result + "success"
        } catch {
            return result + "\(stage):\(String(reflecting: error))"
        }
    }

    private func firstVolume(in directory: URL) throws -> URL { try volumeURLs(in: directory)[0] }
    private func volumeURLs(in directory: URL) throws -> [URL] {
        try FileManager.default.contentsOfDirectory(at: directory, includingPropertiesForKeys: nil)
            .filter { $0.pathExtension == "rar" }
            .sorted { $0.lastPathComponent.localizedStandardCompare($1.lastPathComponent) == .orderedAscending }
    }
}

private final class RARIOFileCounter: @unchecked Sendable {
    private let lock = NSLock()
    private var originals: [ObjectIdentifier: FileByteSource] = [:]
    private var listing = true
    private var byteCount = 0
    private var readCount = 0
    var bytes: Int { lock.withLock { byteCount } }
    var reads: Int { lock.withLock { readCount } }
    func observe(_ source: FileByteSource, _ count: Int) {
        lock.withLock {
            if listing { originals[ObjectIdentifier(source)] = source }
            if originals[ObjectIdentifier(source)] != nil { byteCount += count; readCount += 1 }
        }
    }
    func beginExtraction() { lock.withLock { listing = false; byteCount = 0; readCount = 0 } }
}
